// Turn the WhatsApp Cloud API webhook payload into one flat item per inbound message.
// Status callbacks (sent / delivered / read) carry no "messages" array and are dropped here.
const out = [];

for (const item of $input.all()) {
  const payload = item.json.value ?? item.json; // tolerate both trigger output shapes
  const messages = payload.messages ?? [];
  const contacts = payload.contacts ?? [];
  const phoneNumberId = payload.metadata?.phone_number_id ?? null;

  for (const msg of messages) {
    const contact = contacts.find((c) => c.wa_id === msg.from) ?? contacts[0] ?? {};
    let kind = 'text';
    let text = '';
    let mediaId = null;

    switch (msg.type) {
      case 'text':
        text = msg.text?.body ?? '';
        break;
      case 'audio': // voice notes arrive as audio with voice=true
        kind = 'audio';
        mediaId = msg.audio?.id ?? null;
        break;
      case 'interactive':
        text = msg.interactive?.button_reply?.title ?? msg.interactive?.list_reply?.title ?? '';
        break;
      case 'button':
        text = msg.button?.text ?? '';
        break;
      default:
        kind = 'unsupported';
        text = `[The person sent an attachment of type "${msg.type}", which this assistant cannot read.]`;
    }

    out.push({
      json: {
        phone: msg.from,                       // E.164 without "+", used as memory + state key
        name: contact.profile?.name ?? '',
        messageId: msg.id,
        phoneNumberId,                          // reply from the same business number
        kind,
        text: text.trim(),
        mediaId,
        receivedAt: new Date(Number(msg.timestamp) * 1000).toISOString(),
      },
    });
  }
}

return out;

// Merge the inbound message with its handoff state row (if any) and decide whether the bot may answer.
// The Data Table lookup returns an empty item when the contact has no row yet (alwaysOutputData).
const results = [];
const messages = $('Normalize Message').all();

$input.all().forEach((stateItem, i) => {
  const idx = stateItem.pairedItem?.item ?? i; // keep message <-> state row aligned
  const msg = (messages[idx] ?? messages[0]).json;
  const row = stateItem.json ?? {};
  const pausedUntil = row.paused_until ? new Date(row.paused_until) : null;
  const pauseActive = row.paused === true && (!pausedUntil || pausedUntil.getTime() > Date.now());

  results.push({
    json: {
      ...msg,
      botPaused: pauseActive,
      pausedReason: pauseActive ? (row.reason ?? '') : '',
    },
    pairedItem: { item: i },
  });
});

return results;

// Static knowledge base for the fictional Northwind Dental clinic.
// Replace these entries with your own business facts. Keep answers short and factual.
const FAQ = [
  { topic: 'hours', keywords: ['hour', 'open', 'close', 'schedule', 'weekend', 'saturday', 'sunday'],
    answer: 'Monday to Friday 8:00-18:00, Saturday 9:00-13:00, closed Sunday and public holidays. Consultation calls are booked in 20-minute slots during these hours.' },
  { topic: 'location', keywords: ['where', 'address', 'location', 'parking', 'directions'],
    answer: '100 Example Avenue, Suite 2, Springfield (fictional address). Free parking behind the building; wheelchair accessible.' },
  { topic: 'services', keywords: ['service', 'treatment', 'clean', 'whiten', 'implant', 'aligner', 'braces', 'filling', 'crown', 'root canal', 'kids', 'children'],
    answer: 'General and family dentistry (check-ups, cleanings, fillings), crowns, root canal treatment, teeth whitening, clear aligners and implant consultations. Children are welcome from age 3.' },
  { topic: 'pricing', keywords: ['price', 'cost', 'how much', 'fee', 'quote', 'payment plan', 'financing'],
    answer: 'Prices depend on an exam and are not given over chat. The front desk explains costs and payment plan options on the free consultation call.' },
  { topic: 'insurance', keywords: ['insurance', 'ppo', 'coverage', 'plan', 'covered'],
    answer: 'The clinic works with many dental insurance plans. Coverage is verified by the front desk before treatment; no policy numbers are collected over WhatsApp.' },
  { topic: 'new patients', keywords: ['new patient', 'first visit', 'register', 'accepting'],
    answer: 'New patients are welcome. The first step is a free 20-minute consultation call with the front desk, then an in-person exam.' },
  { topic: 'emergencies', keywords: ['emergency', 'pain', 'swelling', 'broken', 'knocked', 'bleeding', 'urgent'],
    answer: 'Same-day emergency slots are reserved on weekdays. A team member handles emergencies directly. For trouble breathing or swallowing, call the local emergency number.' },
  { topic: 'cancellation', keywords: ['cancel', 'reschedule', 'change appointment'],
    answer: 'Appointments can be changed or cancelled up to 24 hours in advance by messaging the clinic; a team member will confirm.' },
];

const q = String(query ?? '').toLowerCase();
const hits = FAQ.filter((f) => f.keywords.some((k) => q.includes(k)));
const selected = hits.length > 0 ? hits : FAQ;
return selected.map((f) => `${f.topic}: ${f.answer}`).join('\n');

